// Lägg dina styrande dokument här som textblock.
// Varje objekt = ett dokument eller kapitel.
// source = dokumentnamn som visas i mailen under 'Notera särskilt'.
//
// Tips: chunka långa dokument i avsnitt om ~500 ord för bättre träffsäkerhet.

const documents = [
  {
    source: "Länsstyrelseinstruktionen (SFS 2017:868)",
    content: "Länsstyrelsen ska verka för att nationella mål får genomslag i länet samtidigt som hänsyn tas till regionala förhållanden och förutsättningar. Länsstyrelsen ska utifrån ett statligt helhetsperspektiv arbeta sektorsövergripande och inom myndighetens ansvarsområde samordna olika samhällsintressen och statliga myndigheters insatser."
  },
  {
    source: "Regleringsbrev 2026 — Länsstyrelsen Västra Götaland",
    content: "Klistra in relevant text från regleringsbrevet här."
  },
  {
    source: "Regional utvecklingsstrategi VG2030",
    content: "Klistra in relevant text från VG2030 här."
  },
  {
    source: "Handlingsplan civilt försvar 2024–2026",
    content: "Klistra in relevant text från handlingsplanen här."
  }
];

// Chunka varje dokument i block om max 500 ord
const CHUNK_SIZE = 500;
const chunks = [];

documents.forEach(doc => {
  const words = doc.content.split(/\s+/);
  for (let i = 0; i < words.length; i += CHUNK_SIZE) {
    chunks.push({
      source: doc.source,
      content: words.slice(i, i + CHUNK_SIZE).join(' '),
    });
  }
});

return chunks.map(c => ({ json: c }));

// Kombinera embedding med chunk-metadata från Load Documents
const embedding = $json.data[0].embedding;
const source = $('Load Documents').item.json.source;
const content = $('Load Documents').item.json.content;

return [{ json: { embedding, source, content } }];
